#include "stdafx.h"#include "HcdElementBase.h"#include <HcdMemoryService.h>#include <HcdDataTypes_.h>struct SAO_P{#include "PrivateVars/AO.h"};class KAO : public KHcdElementBase  , protected SAO_P{  W_AO *m_pHardware;public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _AO("AO", KAO::Create);IHcdElement *KAO::Create(){  return new KAO;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KAO, 12 )void KAO::InitParm(){#include "PrivateVars/AO.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KAO::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;  m_pHardware = (W_AO*)KMemoryServiceHCD::Instance().IoCreateObj( szName, W_AO::TypeID, domain );  m_pSharedObject = (BYTE*)m_pHardware;  m_pSharedVarsInfo = new SVarInfo;  AddSharedField( "RAW", NULL, offsetof(W_AO, W_AO::RAW), ehtAnalog32, sizeof(tAnalog32), 1 );}void KAO::StepCalc( SStepCalcParams &params ){  OUTD0 = INU0;  m_pHardware->RAW = INU0;}